import { action, Flow, Subflow, wfa, trigger } from '@servicenow/sdk/automation'
import { StringColumn, BooleanColumn } from '@servicenow/sdk/core'

// Test Subflow with Inline Scripts
export const testSubflowWithInlineScripts = Subflow(
    {
        $id: Now.ID['test_subflow_inline_scripts'],
        name: 'Test - Process User Access - Inline Script Example',
        description: 'Test subflow with inline scripts',
        inputs: {
            userName: StringColumn({
                label: 'User Name',
                mandatory: true,
            }),
            userEmail: StringColumn({
                label: 'User Email',
                mandatory: true,
            }),
            needsVPN: BooleanColumn({
                label: 'Needs VPN Access',
                mandatory: false,
            }),
        },
        outputs: {},
    },
    (params) => {
        // Log with inline script
        wfa.action(
            action.core.log,
            { $id: Now.ID['test_log_provisioning_start'], annotation: 'Log provisioning with inline script' },
            {
                log_level: 'info',
                log_message: wfa.inlineScript(`
                    var user = fd_data.subflow_inputs.userName;
                    var email = fd_data.subflow_inputs.userEmail;
                    var timestamp = new Date().toISOString();
                    return 'Starting user provisioning for ' + user + ' (' + email + ') at ' + timestamp;
                `),
            }
        )

        // Create user account
        wfa.action(
            action.core.createRecord,
            { $id: Now.ID['test_create_user_account'], annotation: 'Create user in sys_user table' },
            {
                table_name: 'sys_user',
                values: `user_name=${wfa.dataPill(params.inputs.userName, 'string')}^email=${wfa.dataPill(params.inputs.userEmail, 'string')}^active=true`,
            }
        )

        // Send welcome email with inline script
        wfa.action(
            action.core.sendEmail,
            { $id: Now.ID['test_send_welcome_email'], annotation: 'Send personalized welcome email' },
            {
                ah_to: `${wfa.dataPill(params.inputs.userEmail, 'string')}`,
                ah_subject: `Welcome ${wfa.dataPill(params.inputs.userName, 'string')}!`,
                ah_body: wfa.inlineScript(`
                    var user = fd_data.sub_flow.inputs.userName;
                    var userId = fd_data._2__create_record.record;
                    var vpn = fd_data.sub_flow.inputs.needsVPN ? 'with VPN access' : 'without VPN access';
                    
                    return 'Dear ' + user + ',\\n\\n' +
                           'Your account has been created ' + vpn + '.\\n' +
                           'User ID: ' + userId + '\\n\\n' +
                           'Welcome aboard!';
                `),
            }
        )
    }
)

// Test Flow that uses the subflow
export const flowWithSubflow = Flow(
    {
        $id: Now.ID['test_flow_with_subflow'],
        name: 'Test - Flow with Subflow',
        description: 'Test flow that calls subflow with inline scripts',
        runAs: 'system',
        runWithRoles: [],
        flowPriority: 'MEDIUM',
    },
    wfa.trigger(
        trigger.record.created,
        { $id: Now.ID['test_trigger_subflow'] },
        {
            table: 'sys_user',
            condition: '',
            run_on_extended: 'false',
            run_flow_in: 'background',
            run_when_user_list: [],
            run_when_setting: 'both',
            run_when_user_setting: 'any',
        }
    ),
    () => {
        wfa.subflow(
            testSubflowWithInlineScripts,
            { $id: Now.ID['test_call_subflow'], annotation: 'Call test subflow' },
            {
                userName: wfa.inlineScript("return fd_data.trigger.current.name || 'test.user'"),
                userEmail: wfa.inlineScript("return fd_data.trigger.current.email || 'test@example.com'"),
                needsVPN: wfa.inlineScript("return fd_data.trigger.current.vip == 'true'"),
            }
        )
    }
)
